package app.studyforge.mobile;
import org.junit.Test;
import org.json.*;
import static org.junit.Assert.*;

public class FeatureTest {
    JSONObject program() throws Exception {return Json.object("title","복습 도구","description","실제 계산 기능","changes",Json.array("새 기능"),"html","<div id='queue'></div>","css","body{color:green}","js","window.featureLogic={square:n=>n*n};","tests",Json.array(Json.object("name","계산","code","if(featureLogic.square(2)!==4)throw Error('bad');return true;")),"capabilities",Json.array("study.read","state.write","practice.open"),"hostPatch",new JSONObject(),"unsupported",new JSONArray());}
    JSONObject workspace() throws Exception {return Json.object("settings",Json.object("theme","sage","custom","old"),"generationMode","concept","count",5,"dataset",Json.object("id","d","title","학습실","questions",Json.array(Json.object("id","q","stem","문제","answer",0)),"answers",Json.object("q",Json.object("selected",1)),"uncertain",Json.object("q",true)),"accountToken","secret","sources",Json.array(Json.object("images","not-for-feature")));}
    JSONObject draft(String id,JSONObject p) throws Exception {return Json.object("id",id,"program",p,"request","기능 추가","checks",Json.object("passed",true));}
    @Test public void validatesRealCodeAndRejectsUnsupportedHostCapabilities() throws Exception {JSONObject p=program();assertEquals(p.getString("js"),FeatureProgram.validate(p).getString("js"));for(String html:new String[]{"<script>alert(1)</script>","<iframe src='x'>","<img onerror='x'>","<meta http-equiv='refresh'>"}){p=program().put("html",html);try{FeatureProgram.validate(p);fail();}catch(Exception expected){}}p=program().put("capabilities",Json.array("token.read"));try{FeatureProgram.validate(p);fail();}catch(Exception expected){}p=program().put("hostPatch",Json.object("deleteAll",true));try{FeatureProgram.validate(p);fail();}catch(Exception expected){}}
    @Test public void normalizesUiPatchAndRejectsBadGeneration() throws Exception {JSONObject p=program().put("hostPatch",Json.object("ui",Json.object("fontSize",20)));assertEquals("sage",FeatureProgram.validate(p).getJSONObject("hostPatch").getJSONObject("ui").getString("theme"));for(JSONObject g:new JSONObject[]{Json.object("count",0),Json.object("count",2.5),Json.object("generationMode","delete"),Json.object("difficulty","impossible"),Json.object("secret","x")})try{FeatureProgram.patch(Json.object("generation",g));fail();}catch(Exception expected){}}
    @Test public void createModifyRollbackPreservesQuestionsAndFeatureState() throws Exception {JSONObject w=workspace();String dataset=w.getJSONObject("dataset").toString();w.put("featureData",Json.object("f:d",Json.object("notes","keep")));JSONObject p=program().put("hostPatch",Json.object("generation",Json.object("custom","new")));JSONObject one=FeatureVersions.apply(w,draft("f",p));assertEquals("new",one.getJSONObject("settings").getString("custom"));JSONObject two=FeatureVersions.apply(one,draft("f",program().put("title","개정판")));assertEquals(2,FeatureVersions.find(two.getJSONArray("features"),"f").getInt("revision"));JSONObject back=FeatureVersions.undo(two,"f");assertEquals(1,FeatureVersions.find(back.getJSONArray("features"),"f").getInt("revision"));back=FeatureVersions.undo(back,"f");assertFalse(FeatureVersions.find(back.getJSONArray("features"),"f").getBoolean("enabled"));assertEquals("old",back.getJSONObject("settings").getString("custom"));assertEquals(dataset,back.getJSONObject("dataset").toString());assertEquals("keep",back.getJSONObject("featureData").getJSONObject("f:d").getString("notes"));assertEquals("old",w.getJSONObject("settings").getString("custom"));}
    @Test public void undoDoesNotOverwriteLaterManualSettings() throws Exception {JSONObject w=FeatureVersions.apply(workspace(),draft("f",program().put("hostPatch",Json.object("generation",Json.object("custom","by feature")))));w.getJSONObject("settings").put("custom","user changed later");JSONObject back=FeatureVersions.undo(w,"f");assertEquals("user changed later",back.getJSONObject("settings").getString("custom"));}
    @Test public void featureReceivesOnlySelectedStudyDataNeverCredentialsOrOriginals() throws Exception {JSONObject c=FeatureBuilder.context(workspace(),program(),Json.object("note","local"));assertFalse(c.toString().contains("secret"));assertFalse(c.toString().contains("not-for-feature"));assertEquals("d",c.getJSONObject("data").getString("id"));JSONObject p=program().put("capabilities",new JSONArray());assertEquals(0,FeatureBuilder.context(workspace(),p,null).getJSONObject("data").length());}
    @Test public void validatesPracticeScopeStateSizeAndWireDepth() throws Exception {assertEquals("q",FeatureBuilder.practice(workspace(),Json.array("q")).getString(0));for(JSONArray ids:new JSONArray[]{Json.array("other"),Json.array("q","q"),new JSONArray()})try{FeatureBuilder.practice(workspace(),ids);fail();}catch(Exception expected){}try{FeatureBuilder.state(Json.object("s","x".repeat(32001)));fail();}catch(Exception expected){}assertEquals("[[[[",FeatureWire.parse("{\"value\":\"[[[[\"}").getString("value"));try{FeatureWire.parse("{\"x\":"+"[".repeat(41)+"0"+"]".repeat(41)+"}");fail();}catch(Exception expected){}}
    @Test public void generatorReviewsActualProgramAndKeepsFailedDraftOut() throws Exception {final int[] calls={0};JSONObject result=FeatureBuilder.build("복습 기능",null,workspace(),(rules,text)->{calls[0]++;return program().put("title",calls[0]==1?"초안":"검수판");},s->{});assertEquals(2,calls[0]);assertEquals("검수판",result.getString("title"));try{FeatureBuilder.build("없는 권한",null,workspace(),(r,t)->program().put("capabilities",Json.array("files.delete")),s->{});fail();}catch(Exception expected){}}
}
